import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 32
#define TILE_H 8
#define OH_PER_THREAD 8
#define VEC 4
__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h,
    int stride, int padding, int dilation,
    bool has_bias)
{
    extern __shared__ float smem[];
    int tx = threadIdx.x; // 0..(TILE_W/VEC - 1)
    int ty = threadIdx.y;
    int bc = blockIdx.x; // combined batch*channel index
    int n = bc / channels;
    int c = bc % channels;
    int ow_base = blockIdx.y * TILE_W;
    int tile_h_out = TILE_H * OH_PER_THREAD;
    int oh_base = blockIdx.z * tile_h_out;
    int sh_h = (tile_h_out - 1) * stride + (kernel_h - 1) * dilation + 1;
    int base_h = oh_base * stride - padding;
    int col_base = tx * VEC;
    // Cooperatively load the reusable input column-strip (over the height
    // dimension) into shared memory so that adjacent output rows within
    // this tile can reuse loaded input values instead of re-fetching from
    // global memory for every kernel_h tap. Each thread now also computes
    // OH_PER_THREAD output rows (register blocking) to amortize the cost
    // of the shared-memory staging over more useful work per thread, and
    // handles VEC consecutive output columns so that shared-memory reads
    // during the compute phase and the final output stores can be done
    // with vectorized float4 accesses for better memory coalescing.
    for (int r = ty; r < sh_h; r += blockDim.y) {
        int in_h_idx = base_h + r;
        #pragma unroll
        for (int v = 0; v < VEC; ++v) {
            int ow = ow_base + col_base + v;
            float val = 0.0f;
            if (in_h_idx >= 0 && in_h_idx < in_h && ow < out_w) {
                int in_w_idx = ow * stride - padding;
                if (in_w_idx >= 0 && in_w_idx < in_w) {
                    int input_offset = ((n * channels + c) * in_h + in_h_idx) * in_w + in_w_idx;
                    val = input[input_offset];
                }
            }
            smem[r * TILE_W + col_base + v] = val;
        }
    }
    __syncthreads();
    int weight_offset = c * kernel_h;
    #pragma unroll
    for (int i = 0; i < OH_PER_THREAD; ++i) {
        int oh = oh_base + ty + i * TILE_H;
        if (oh < out_h) {
            float sums[VEC];
            #pragma unroll
            for (int v = 0; v < VEC; ++v) sums[v] = 0.0f;
            #pragma unroll
            for (int kh = 0; kh < kernel_h; ++kh) {
                int row_in_tile = (ty + i * TILE_H) * stride + kh * dilation;
                float4 in_val4 = *reinterpret_cast<const float4*>(&smem[row_in_tile * TILE_W + col_base]);
                float w_val = weight[weight_offset + kh];
                sums[0] += in_val4.x * w_val;
                sums[1] += in_val4.y * w_val;
                sums[2] += in_val4.z * w_val;
                sums[3] += in_val4.w * w_val;
            }
            if (has_bias) {
                float b = bias[c];
                #pragma unroll
                for (int v = 0; v < VEC; ++v) sums[v] += b;
            }
            int ow_start = ow_base + col_base;
            int out_row_offset = ((n * channels + c) * out_h + oh) * out_w;
            if ((ow_start + VEC <= out_w) && (((out_row_offset + ow_start) & 3) == 0)) {
                float4 out_val4;
                out_val4.x = sums[0];
                out_val4.y = sums[1];
                out_val4.z = sums[2];
                out_val4.w = sums[3];
                *reinterpret_cast<float4*>(&output[out_row_offset + ow_start]) = out_val4;
            } else {
                #pragma unroll
                for (int v = 0; v < VEC; ++v) {
                    int ow = ow_start + v;
                    if (ow < out_w) {
                        output[out_row_offset + ow] = sums[v];
                    }
                }
            }
        }
    }
}
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);
    int kernel_h = weight.size(2); // weight shape: (channels, 1, kernel_h, 1)
    int out_h = (in_h + 2 * padding - dilation * (kernel_h - 1) - 1) / stride + 1;
    int out_w = (in_w + 2 * padding - 1) / stride + 1;
    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());
    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    dim3 block(TILE_W / VEC, TILE_H);
    int tile_h_out = TILE_H * OH_PER_THREAD;
    dim3 grid(batch_size * channels,
              (out_w + TILE_W - 1) / TILE_W,
              (out_h + tile_h_out - 1) / tile_h_out);
    int sh_h = (tile_h_out - 1) * stride + (kernel_h - 1) * dilation + 1;
    size_t shared_mem_size = static_cast<size_t>(sh_h) * TILE_W * sizeof(float);
    depthwise_conv2d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, channels,
        in_h, in_w,
        out_h, out_w,
        kernel_h,
        stride, padding, dilation,
        has_bias);
    return output;
}
"""

depthwise_conv2d_cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias);
"""

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel,
    using a custom CUDA kernel fused for the (kernel_size, 1) depthwise convolution.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # weight shape: (in_channels, 1, kernel_size, 1) matching nn.Conv2d depthwise groups=in_channels
        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in = kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.depthwise_conv2d = depthwise_conv2d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        if self.has_bias:
            bias = self.bias.contiguous().cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return self.depthwise_conv2d.depthwise_conv2d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.has_bias
        )

